namespace Slic3r { namespace GUI { namespace JusPrin { namespace Home {

namespace {

boost::filesystem::path home_page_path()
{
    return boost::filesystem::path(resources_dir()) / "jusprin" / "home" / "index.html";
}

wxString home_page_url()
{
    if (const char* dev = std::getenv("JUSPRIN_HOME_DEV_URL"); dev != nullptr && *dev != '\0')
        return wxString::FromUTF8(dev);
    const boost::filesystem::path page = home_page_path();
    if (!boost::filesystem::exists(page))
        return {};
    return wxFileSystem::FileNameToURL(wxFileName(wxString::FromUTF8(page.string())));
}

} // namespace

HomeWebView::HomeWebView(wxWindow* parent, const ShellTheme& theme, MainFrame& frame)
    : wxPanel(parent, wxID_ANY), m_theme(theme), m_live_timer(this)
{
    Bind(wxEVT_TIMER, &HomeWebView::on_live_tick, this, m_live_timer.GetId());
    m_backend = std::make_unique<OrcaHomeBackend>(frame);
    m_host    = std::make_unique<HomeHost>(*m_backend, [this](const std::string& envelope) {
        if (m_webview == nullptr)
            return;
        wxString script = "window.__jusprinBridge && window.__jusprinBridge.deliver(";
        script += wxString::FromUTF8(envelope);
        script += ")";
        WebView::RunScript(m_webview, script);
    });

    auto* sizer = new wxBoxSizer(wxVERTICAL);
    SetSizer(sizer);

    m_error = new wxStaticText(this, wxID_ANY, wxEmptyString);
    m_error->Hide();
    sizer->Add(m_error, 0, wxALL, FromDIP(16));

    apply_appearance(GUI_App::dark_mode());

    const wxString url = home_page_url();
    if (url.empty()) {
        show_page_error(_L("The packaged Home page is missing from this build."));
        return;
    }
    m_webview = WebView::CreateWebView(this, url);
    if (m_webview == nullptr) {
        show_page_error(_L("The system web view could not be created."));
        return;
    }
    sizer->Add(m_webview, 1, wxEXPAND);
    m_webview->Bind(wxEVT_WEBVIEW_SCRIPT_MESSAGE_RECEIVED, &HomeWebView::on_script_message, this);
    m_webview->Bind(wxEVT_WEBVIEW_ERROR, &HomeWebView::on_load_error, this);
    m_webview->Bind(wxEVT_WEBVIEW_NAVIGATING, [this](wxWebViewEvent& event) {
        // Every (re)load needs a fresh handshake before other traffic.
        m_host->reset_page();
        event.Skip();
    });
}

HomeWebView::~HomeWebView()
{
    // The webview outlives this frame's teardown callbacks in wx's child
    // destruction order; drop the host first so it cannot run script against a
    // dying view, then the backend it reads through.
    m_live_timer.Stop();
    m_host.reset();
    m_backend.reset();
}

void HomeWebView::apply_appearance(bool dark)
{
    const ShellPalette& palette = m_theme.palette(dark);
    SetBackgroundColour(palette.surface_canvas);
    style_label(*m_error, m_theme, TextRole::Body, palette.text_secondary);
    m_host->push_appearance(dark);
    Refresh();
}

void HomeWebView::refresh(const std::string& added) { m_host->push_state(added); }

void HomeWebView::set_live(bool live)
{
    if (!live)
        m_live_timer.Stop();
    else if (!m_live_timer.IsRunning())
        m_live_timer.Start(1000);
}

void HomeWebView::on_live_tick(wxTimerEvent&)
{
    // Nothing to update while the printer conversation covers the page or the
    // window is minimized. The first tick after either is over catches up:
    // the comparison is against what was last sent, not the last tick.
    if (const auto* top = dynamic_cast<const wxTopLevelWindow*>(wxGetTopLevelParent(this)); top != nullptr && top->IsIconized())
        return;
    // Print hosts are read on their own schedule, and the conversation that
    // covers the page reads them too, so they are kept fresh either way.
    Printers::refresh_host_readings();
    if (m_webview == nullptr || !m_webview->IsShownOnScreen())
        return;
    m_host->refresh_if_changed();
}

void HomeWebView::on_script_message(wxWebViewEvent& event)
{
    m_host->on_page_message(event.GetString().ToUTF8().data());
}

void HomeWebView::on_load_error(wxWebViewEvent& event)
{
    BOOST_LOG_TRIVIAL(error) << "JusPrin Home page failed to load: " << event.GetString().ToUTF8();
    show_page_error(_L("The Home page failed to load."));
}

void HomeWebView::show_page_error(const wxString& reason)
{
    m_error->SetLabel(reason);
    m_error->Show();
    Layout();
}

}}}} // namespace Slic3r::GUI::JusPrin::Home
#pragma once

// The native side of the jusprin-home-bridge protocol: it answers the page's
// handshake, sends the snapshot the backend assembles, and turns the page's
// messages into backend actions. It holds no project or printer state of its
// own -- every hello is answered with a complete snapshot, so a page reload is
// always recoverable.
//
// No wx and no Orca types: the transport is injected and the application is
// reached through IHomeBackend, so the protocol can be exercised in a GUI-free
// test with a fake backend.

#include "HomeBackend.hpp"

#include <nlohmann/json_fwd.hpp>

#include <functional>
#include <string>

namespace Slic3r { namespace GUI { namespace JusPrin { namespace Home {

class HomeHost
{
public:
    // Receives one serialised envelope to hand to the page.
    using Send = std::function<void(const std::string&)>;

    HomeHost(IHomeBackend& backend, Send send);

    // A (re)load invalidates the handshake; nothing but hello is answered
    // until the new page introduces itself.
    void reset_page();

    void on_page_message(const std::string& text);

    // `added` names a printer the conversation just added: this one push
    // leads the printers list with it and asks the page to highlight it.
    void push_state(const std::string& added = {});
    // The live path, for a screen that stays up while its printers change
    // under it: re-reads only the printers, and sends the whole state only
    // when a card would look different from the last state sent. The printer
    // the last push_state named keeps its place and its highlight, so a live
    // push never reorders the column or cuts the highlight short. Projects
    // are re-read with any send; nothing that changes them alone happens
    // while Home is on screen. Returns whether it sent.
    bool refresh_if_changed();
    void push_appearance(bool dark);

    bool               connected() const { return m_connected; }
    unsigned long long messages_sent() const { return m_sent; }
    unsigned long long messages_received() const { return m_received; }

private:
    Snapshot collect() const;
    // The backend's printers, led by `m_added` when it is listed.
    std::vector<PrinterEntry> ordered_printers() const;
    void     send_state(Snapshot snapshot);
    void     send(const std::string& type, const nlohmann::json& payload, const std::string& correlation = {});

    IHomeBackend&      m_backend;
    Send               m_send;
    bool               m_connected{false};
    unsigned long long m_sent{0};
    unsigned long long m_received{0};
    unsigned long long m_next_id{1};
    // What the last push_state named, and the printers of the last state
    // sent, serialised as the page receives them: what refresh_if_changed
    // compares against.
    std::string        m_added;
    std::string        m_sent_printers;
};

}}}} // namespace Slic3r::GUI::JusPrin::Home
// The transport, handshake, and message identity shared by every JusPrin web
// surface. It renders nothing and knows no page's message types: a page names
// its protocol once, and consumes the connection state and the validated host
// envelopes. Reload safety comes from the protocol design -- every hello is
// answered with complete native state.

export type ConnectionState =
  | 'connecting'
  | 'connected'
  | 'no-transport'
  | 'incompatible'
  | 'timeout';

export interface Envelope<T = unknown> {
  protocol: string;
  version: number;
  id: string;
  type: string;
  correlationId?: string;
  sessionId?: string;
  revision?: number;
  payload: T;
}

// Which protocol this page speaks, from its own protocol.json.
export interface ProtocolIdentity {
  name: string;
  version: number;
  capabilities: string[];
}

export interface Transport {
  post(json: string): void;
}

export interface BridgeClientOptions {
  // The native transport can appear slightly after the page starts running:
  // wx injects window.wx into an already-loading page from native code. The
  // client therefore re-polls this factory before declaring no-transport.
  getTransport: () => Transport | null;
  onEnvelope: (envelope: Envelope) => void;
  onConnectionChange: (state: ConnectionState, detail?: string) => void;
  handshakeTimeoutMs?: number;
  transportRetryMs?: number;
  transportRetryLimit?: number;
  // Injectable for deterministic tests.
  scheduleTimeout?: (fn: () => void, ms: number) => unknown;
  cancelTimeout?: (handle: unknown) => void;
}

declare global {
  interface Window {
    wx?: { postMessage(json: string): void };
    __jusprinBridge?: { deliver(envelope: unknown): void };
  }
}

export function nativeTransport(): Transport | null {
  if (typeof window !== 'undefined' && window.wx && typeof window.wx.postMessage === 'function') {
    return { post: (json) => window.wx!.postMessage(json) };
  }
  return null;
}

export function envelopeMatches(value: unknown, protocolName: string): value is Envelope {
  if (typeof value !== 'object' || value === null) return false;
  const env = value as Record<string, unknown>;
  return (
    env.protocol === protocolName &&
    typeof env.version === 'number' &&
    typeof env.id === 'string' &&
    typeof env.type === 'string'
  );
}

export class SharedBridgeClient {
  private readonly protocol: ProtocolIdentity;
  private readonly options: BridgeClientOptions;
  private nextId = 1;
  private handshakeHandle: unknown = null;
  private state: ConnectionState = 'connecting';
  private transport: Transport | null = null;
  private transportAttempts = 0;

  constructor(protocol: ProtocolIdentity, options: BridgeClientOptions) {
    this.protocol = protocol;
    this.options = options;
  }

  connectionState(): ConnectionState {
    return this.state;
  }

  start(): void {
    if (typeof window !== 'undefined') {
      window.__jusprinBridge = { deliver: (envelope: unknown) => this.deliver(envelope) };
    }
    this.beginHandshake();
  }

  retry(): void {
    this.transportAttempts = 0;
    this.beginHandshake();
  }

  private schedule(fn: () => void, ms: number): unknown {
    const schedule = this.options.scheduleTimeout ?? ((f, m) => setTimeout(f, m));
    return schedule(fn, ms);
  }

  private cancel(handle: unknown): void {
    const cancel = this.options.cancelTimeout ?? ((h) => clearTimeout(h as number));
    cancel(handle);
  }

  private beginHandshake(): void {
    this.transport = this.options.getTransport();
    if (!this.transport) {
      const limit = this.options.transportRetryLimit ?? 40;
      if (this.transportAttempts < limit) {
        this.transportAttempts += 1;
        this.setState('connecting');
        this.schedule(() => {
          if (this.state === 'connecting' && !this.transport) this.beginHandshake();
        }, this.options.transportRetryMs ?? 250);
      } else {
        this.setState('no-transport', 'The native message handler (window.wx) is not present.');
      }
      return;
    }
    this.setState('connecting');
    this.post('hello', {
      protocolVersions: [this.protocol.version],
      capabilities: this.protocol.capabilities,
    });
    const timeoutMs = this.options.handshakeTimeoutMs ?? 10000;
    if (this.handshakeHandle !== null) this.cancel(this.handshakeHandle);
    this.handshakeHandle = this.schedule(() => {
      if (this.state === 'connecting') {
        this.setState('timeout', 'The native host did not answer the hello handshake.');
      }
    }, timeoutMs);
  }

  send(type: string, payload: unknown): void {
    this.post(type, payload);
  }

  private post(type: string, payload: unknown): void {
    if (!this.transport) return;
    const envelope: Envelope = {
      protocol: this.protocol.name,
      version: this.protocol.version,
      id: `w-${this.nextId++}`,
      type,
      payload,
    };
    this.transport.post(JSON.stringify(envelope));
  }

  deliver(raw: unknown): void {
    if (!envelopeMatches(raw, this.protocol.name)) return; // not this protocol; ignore
    const envelope = raw;
    if (envelope.type === 'hello_ack') {
      this.cancelHandshakeTimer();
      this.setState('connected');
    } else if (envelope.type === 'hello_reject') {
      this.cancelHandshakeTimer();
      const payload = envelope.payload as { message?: string } | undefined;
      this.setState('incompatible', payload?.message ?? 'The host rejected this protocol version.');
    }
    this.options.onEnvelope(envelope);
  }

  private cancelHandshakeTimer(): void {
    if (this.handshakeHandle !== null) {
      this.cancel(this.handshakeHandle);
      this.handshakeHandle = null;
    }
  }

  private setState(state: ConnectionState, detail?: string): void {
    this.state = state;
    this.options.onConnectionChange(state, detail);
  }
}

