        <div className="setup-error-details">
          <button type="button" onClick={() => setDetails(!details)}>
            <span className={`jp-icon jp-icon-chevron-${details ? 'down' : 'right'}`} aria-hidden="true" /> Technical output
          </button>
          {details && <pre>{diagnostic}</pre>}
        </div>
      )}
    </div>
  );
}

