// Usage: node edit.js <edits.json>; edits.json = [[path, [[old, new], ...]], ...]
// Keeps each file's own line endings; fails without writing if any old string is missing or repeated.
const fs = require('fs');
const plan = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
const out = [];
for (const [path, pairs] of plan) {
  let s = fs.readFileSync(path, 'utf8');
  const eol = s.includes('\r\n') ? '\r\n' : '\n';
  for (let [a, b] of pairs) {
    a = a.split('\n').join(eol);
    b = b.split('\n').join(eol);
    const first = s.indexOf(a);
    if (first < 0) { console.error('MISSING in ' + path + ':\n' + a); process.exit(1); }
    if (s.indexOf(a, first + 1) >= 0) { console.error('REPEATED in ' + path + ':\n' + a); process.exit(1); }
    s = s.slice(0, first) + b + s.slice(first + a.length);
  }
  out.push([path, s]);
}
for (const [path, s] of out) fs.writeFileSync(path, s);
console.log('edited ' + out.length + ' files');

