input.content:
// Moves the language list and the language names out of
// PreferencesDialog::create_item_language_combobox into two static functions,
// keeping their lines as they were.
const fs = require('fs');
const path = 'src/slic3r/GUI/Preferences.cpp';
let s = fs.readFileSync(path, 'utf8');
const eol = s.includes('\r\n') ? '\r\n' : '\n';
const lines = s.split(eol);
const find = (text, from = 0) => {
  const i = lines.findIndex((l, k) => k >= from && l === text);
  if (i < 0) { console.error('missing: ' + text); process.exit(1); }
  return i;
};
const start = find('wxBoxSizer *PreferencesDialog::create_item_language_combobox(wxString title, wxString tooltip)');
const listBegin = find('    wxLanguage supported_languages[]{', start);
const listEnd = find('    std::sort(language_infos.begin(), language_infos.end(), [](const wxLanguageInfo *l, const wxLanguageInfo *r) { return l->Description < r->Description; });', start);
const vlistLine = find('    auto vlist = language_infos;', start);
const loopName = find('        auto language_name = vlist[i]->Description;', start);
const chainEnd = find('        if (app_config->get(param) == vlist[i]->CanonicalName) {', start);
// The name chain runs from the line after `auto language_name` up to the blank line before the match.
const chain = lines.slice(loopName + 1, chainEnd - 1);
if (lines[chainEnd - 1] !== '') { console.error('expected a blank line before the match'); process.exit(1); }

const listBody = lines.slice(listBegin, listEnd + 1);
const nameBody = chain.map((l) => l.replace(/vlist\[i\]/g, 'info').replace(/^    /, ''));

const helpers = [
  '// The languages the dialog offers, in the order it lists them. Other',
  '// Preferences windows offer the same ones.',
  'std::vector<const wxLanguageInfo *> PreferencesDialog::offered_languages()',
  '{',
  ...listBody,
  '    return language_infos;',
  '}',
  '',
  '// The name a language is listed by: its own name where the dialog has one.',
  'wxString PreferencesDialog::language_name(const wxLanguageInfo *info)',
  '{',
  '    auto language_name = info->Description;',
  ...nameBody,
  '    return language_name;',
  '}',
  '',
];

const before = lines.slice(0, start);
const head = lines.slice(start, listBegin);
const between = lines.slice(listEnd + 1, vlistLine);
const loopHead = lines.slice(vlistLine + 1, loopName);
const rest = lines.slice(chainEnd - 1);

const out = [
  ...before,
  ...helpers,
  ...head,
  '    // The list and the names are offered_languages() and language_name(),',
  '    // which other Preferences windows share; a rebase keeps changes there.',
  '    const std::vector<const wxLanguageInfo *> language_infos = offered_languages();',
  ...between,
  '    auto vlist = language_infos;',
  ...loopHead,
  '        auto language_name = PreferencesDialog::language_name(vlist[i]);',
  ...rest,
];
fs.writeFileSync(path, out.join(eol));
console.log('moved', listBody.length, 'list lines and', nameBody.length, 'name lines');

