/* The design system's Segmented Control, as the setup screens draw it, for
   any surface: a subtle track holding equal segments, the chosen one filled
   with action/primary. */
.jp-segmented {
  display: flex;
  flex: 0 0 auto;
  box-sizing: border-box;
  height: var(--segmented-height);
  padding: var(--segmented-padding);
  border: var(--segmented-border-width) solid var(--border-subtle);
  border-radius: var(--segmented-radius);
  background: var(--surface-subtle);
}

.jp-segment {
  flex: 1 1 auto;
  height: var(--segmented-segment-height);
  padding: var(--segmented-segment-padding-y) var(--segmented-segment-padding-x);
  border: 0;
  border-radius: var(--segmented-radius);
  background: transparent;
  font: var(--font-label);
  color: var(--text-primary);
  white-space: nowrap;
  cursor: pointer;
}

.jp-segment:hover:enabled,
.jp-segment:active:enabled {
  border: 0;
}

.jp-segment.selected {
  background: var(--action-primary);
  color: var(--action-primary-text);
}

.jp-segment:disabled {
  color: var(--action-disabled-text);
  cursor: default;
}

/* The presets in use, and an object's or a plate's summary: a subtle box. */
  font: var(--font-label);
  color: var(--text-secondary);
}

.printer-form-lead b {
  color: var(--text-primary);
}

/* The design system's Checkbox, with a line of detail under its label. */
.printer-form-check {
  display: flex;
  align-items: flex-start;
  gap: var(--checkbox-label-gap);
  padding: 0;
  border: 0;
  background: transparent;
  font: var(--font-body);
  color: var(--text-primary);
  text-align: left;
  cursor: pointer;
}

.printer-form-check-box {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  width: var(--checkbox-size);
  height: var(--checkbox-size);
  border-radius: var(--checkbox-radius);
  box-shadow: inset 0 0 0 1px var(--border-strong);
  background: var(--surface-canvas);
}

.printer-form-check[aria-checked='true'] .printer-form-check-box {
  background: var(--action-primary);
  box-shadow: inset 0 0 0 1px var(--action-primary);
}

.printer-form-check-box .jp-icon {
  width: var(--checkbox-glyph-size);
  height: var(--checkbox-glyph-size);
  color: var(--action-primary-text);
}

.printer-form-check-copy {
  display: flex;
  flex-direction: column;
}

.printer-form-check-detail {
  font: var(--font-label);
  color: var(--text-secondary);
}

.printer-form-clear {
  display: flex;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--text-secondary);
  cursor: pointer;
}

/* What creating a preset will do, before it does. */
.printer-form-facts {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin: 0;
  padding: 12px;
  border-radius: var(--radius-medium);
  background: var(--surface-subtle);
  font: var(--font-label);
}

.printer-form-facts div {
  display: flex;
  gap: 8px;
}

.printer-form-facts dt {
  flex: 0 0 auto;
  width: var(--form-row-label-width);
  color: var(--text-secondary);
}

.printer-form-facts dd {
  margin: 0;
  color: var(--text-primary);
}
