param([int]$ProcessId, [string]$Title, [string]$Out)
# PrintWindow of one top-level window of the process, by title; never touches the screen or focus.
Add-Type -AssemblyName System.Drawing
Add-Type @"
using System; using System.Text; using System.Runtime.InteropServices;
public static class PW {
  public delegate bool EnumProc(IntPtr h, IntPtr l);
  [StructLayout(LayoutKind.Sequential)] public struct RECT { public int Left, Top, Right, Bottom; }
  [DllImport("user32.dll")] public static extern bool EnumWindows(EnumProc f, IntPtr l);
  [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr h, out uint pid);
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern int GetWindowTextW(IntPtr h, StringBuilder s, int n);
  [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr h);
  [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr h, out RECT r);
  [DllImport("user32.dll")] public static extern bool PrintWindow(IntPtr h, IntPtr hdc, uint f);
  [DllImport("user32.dll")] public static extern bool SetProcessDPIAware();
}
"@
[PW]::SetProcessDPIAware() | Out-Null
$found = [IntPtr]::Zero
$cb = [PW+EnumProc]{ param($h, $l)
  $p = 0; [PW]::GetWindowThreadProcessId($h, [ref]$p) | Out-Null
  if ($p -eq $ProcessId -and [PW]::IsWindowVisible($h)) {
