145	bool PreferencesWindow::on_page_message(const std::string& type, const json& payload)
146	{
147	    if (type == Agent::Protocol::kShellAction && payload.is_object() && payload.value("action", std::string()) == "close") {
148	        CallAfter([this] { close_for({}); });
149	        return true;
150	    }
151	    if (type != Agent::Protocol::kPreferencesAction)
152	        return false;
153	    const Outcome outcome = apply_action(*wxGetApp().app_config, payload);
154	    if (!outcome.error.empty())
155	        BOOST_LOG_TRIVIAL(warning) << "JusPrin Preferences refused an action: " << outcome.error;
156	    // The page draws what is stored, so a refused change springs back.
157	    push_state();
158	    if (outcome.error.empty() && outcome.effect != Effect::None) {
159	        // Not from inside the web view's message handler: some of these open
160	        // a modal dialog or close this window.
161	        CallAfter([this, outcome] { carry_out(outcome); });
162	    }
163	    return true;
164	}
