166	void PreferencesWindow::carry_out(const Outcome& outcome)
167	{
168	    GUI_App& app = wxGetApp();
169	    switch (outcome.effect) {
170	    case Effect::None: break;
171	    case Effect::Theme:
172	        app.apply_dark_mode_setting();
173	        apply_appearance();
174	        break;
175	    case Effect::Language:
176	        if (outcome.value != app.app_config->get("language"))
177	            close_for({AfterClose::Kind::Language, outcome.value});
178	        break;
179	    case Effect::Associate3mf:
180	#ifdef _WIN32
181	        if (outcome.on)
182	            app.associate_files(L"3mf");
183	        else
184	            app.disassociate_files(L"3mf");
185	#endif
186	        break;
187	    case Effect::AssociateModels:
188	#ifdef _WIN32
189	        // What OrcaSlicer's three checkboxes and its dialog's closing pass do
190	        // together: .stp is associated with .step, and only by that pass.
191	        for (const wchar_t* extension : {L"stl", L"step", L"drc"}) {
192	            if (outcome.on)
193	                app.associate_files(extension);
194	            else
195	                app.disassociate_files(extension);
196	        }
197	        if (outcome.on)
198	            app.associate_files(L"stp");
199	#endif
200	        break;
201	    case Effect::AssociateLinks:
202	#ifdef _WIN32
203	        for (const std::wstring& prefix : kModelSiteLinks) {
204	            if (outcome.on)
205	                app.associate_url(prefix);
206	            else
207	                app.disassociate_url(prefix);
208	        }
209	#endif
210	        push_state();
211	        break;
212	    case Effect::ChooseDownloads: {
213	        wxDirDialog dialog(this, _L("Choose Download Directory"), wxString::FromUTF8(app.app_config->get("download_path")),
214	                           wxDD_NEW_DIR_BUTTON);
215	        if (dialog.ShowModal() == wxID_OK) {
216	            app.app_config->set("download_path", dialog.GetPath().ToUTF8().data());
217	            app.app_config->save();
218	            push_state();
219	        }
220	        break;
221	    }
222	    case Effect::ShowVersions: {
223	        const auto folder = boost::filesystem::path(data_dir()) / "jusprin" / "projects";
224	        boost::system::error_code ignored;
225	        boost::filesystem::create_directories(folder, ignored);
226	        desktop_open_any_folder(folder.string());
227	        break;
228	    }
229	    case Effect::CheckUpdates:
230	        // OrcaSlicer's own check, as Help > Check for updates runs it: it says
231	        // what it found in its own dialog.
232	        app.check_new_version_sf(true, 1);
233	        break;
234	    case Effect::OpenUpdate:
235	        if (!app.online_version().url.empty())
236	            wxLaunchDefaultBrowser(wxString::FromUTF8(app.online_version().url));
237	        break;
238	    case Effect::OrcaPreferences: close_for({AfterClose::Kind::OrcaPreferences, {}}); break;
239	    }
240	}
