251	void PreferencesWindow::apply_appearance()
252	{
253	    const bool dark = GUI_App::dark_mode();
254	    SetBackgroundColour(m_theme.palette(dark).surface_raised);
255	    if (m_view != nullptr)
256	        m_view->apply_appearance(dark);
257	    // The title bar follows the theme the way OrcaSlicer's dialogs do.
258	    wxGetApp().UpdateDlgDarkUI(this);
259	    Refresh();
260	}
