262	void PreferencesWindow::on_pump(wxTimerEvent&)
263	{
264	    if (m_view == nullptr)
265	        return;
266	    Agent::AgentHost& host = m_view->host();
267	    host.pump_tools();
268	    host.pump_setup();
269	}
270	
271	bool answers_open_request(size_t open_on_tab, const std::string& highlight_option)
272	{
273	    return !g_opening_orca_dialog && open_on_tab == 0 && highlight_option.empty();
274	}
275	
276	void run_after_close(const AfterClose& after)
277	{
278	    switch (after.kind) {
279	    case AfterClose::Kind::Nothing: break;
280	    case AfterClose::Kind::Language: {
281	        // Rebuilding the main window destroys the shell that opened this
282	        // window, so the reload runs from the application, on its next turn.
283	        const std::string language = after.language;
284	        wxGetApp().CallAfter([language] {
285	            if (wxGetApp().apply_language(language))
286	                wxGetApp().recreate_GUI(_L("Changing application language"));
287	        });
288	        break;
289	    }
290	    case AfterClose::Kind::OrcaPreferences:
291	        wxGetApp().CallAfter([] {
292	            g_opening_orca_dialog = true;
293	            wxGetApp().open_preferences();
294	            g_opening_orca_dialog = false;
295	        });
296	        break;
297	    }
298	}
299	
300	} // namespace Slic3r::GUI::JusPrin::Preferences
