param([string]$Tree, [string]$Tag, [string[]]$Only)
# Runs every self-checking, offline shell-harness mode from one build tree.
# Writes C:\b\h-<Tag>\<mode>.err/.out and a summary line per mode.
$exe = Get-ChildItem -Recurse "$Tree\tests\shell" -Filter shell_integration_harness.exe | Select-Object -First 1
if (-not $exe) { "no harness in $Tree"; exit 1 }
$out = "C:\b\h-$Tag"; New-Item -ItemType Directory -Force $out | Out-Null
$env:WEBVIEW2_USER_DATA_FOLDER = "C:\b\h-$Tag-webview"
$env:PATH = "$($exe.DirectoryName);$Tree\src\Release;$env:PATH"
$plain = @('', '--stock', '--left-pane', '--left-pane-editor', '--classic-switch', '--preset-close',
  '--external-project-history', '--chat-restoration', '--slice-all-cold', '--mcp', '--mcp-setup',
  '--printer-setup', '--printer-menu', '--task-chat', '--task-chat-configured', '--home-live',
  '--printer-live', '--printer-live-no-plugin', '--printer-settings-live', '--filament-settings-live',
  '--print-issues', '--print-issue-readers')
$withDir = @('--reopen-prompt', '--autosave-seed', '--autosave-reopen', '--left-pane-capture', '--left-pane-sliced-capture',
  '--chat-restoration-capture', '--external-project-history-capture', '--printer-menu-capture',
  '--printer-connect-capture', '--recomputing-capture', '--setup-differences-capture', '--reply-choices-capture',
  '--timeline-capture', '--figma-timeline-capture', '--print-issues-capture', '--tool-strip-capture')
$runs = @()
foreach ($m in $plain) { $runs += ,@($m, @()) }
foreach ($m in $withDir) {
  $d = if ($m -like '--autosave-*') { "C:\b\h-$Tag-autosave" } else { "C:\b\h-$Tag-cap\$($m.TrimStart('-'))" }
  $runs += ,@($m, @($d))
}
foreach ($r in $runs) {
  $mode = $r[0]; $extra = $r[1]
  $name = if ($mode) { $mode.TrimStart('-') } else { 'default' }
  if ($Only -and -not ($Only -contains $name)) { continue }
  if ($mode -eq '--autosave-seed' -and (Test-Path "C:\b\h-$Tag-autosave")) { Remove-Item -Recurse -Force "C:\b\h-$Tag-autosave" }
  $args = @(); if ($mode) { $args += $mode }; $args += $extra
  if ($extra.Count -gt 0 -and $mode -notlike '--autosave-*') { New-Item -ItemType Directory -Force $extra[0] | Out-Null }
  $start = Get-Date
  $p = Start-Process $exe.FullName -ArgumentList $args -RedirectStandardError "$out\$name.err" -RedirectStandardOutput "$out\$name.out" -PassThru -WindowStyle Minimized
  if (-not $p.WaitForExit(1200000)) { Stop-Process -Id $p.Id -Force; $code = 'TIMEOUT' } else { $code = $p.ExitCode }
  $fails = @(Select-String -Path "$out\$name.err" -Pattern '\bFAIL\b' -ErrorAction SilentlyContinue | ForEach-Object { $_.Line.Trim() })
  $passes = @(Select-String -Path "$out\$name.err" -Pattern '\bPASS\b' -ErrorAction SilentlyContinue).Count
  $secs = [int]((Get-Date) - $start).TotalSeconds
  "{0,-36} exit={1,-8} pass={2,-4} fail={3,-3} {4}s" -f $name, $code, $passes, $fails.Count, $secs | Tee-Object -Append "$out\summary.txt"
  foreach ($f in $fails) { "    $f" | Tee-Object -Append "$out\summary.txt" }
}

